  $wedClear = $now.Date.AddHours(6); while ($wedClear.DayOfWeek -ne "Wednesday" -or $wedClear -le $now) { $wedClear = $wedClear.AddDays(1) }
  $recentDrop = @{}; foreach ($tx in $TX) { if ($tx.Action -eq "Drop") { try { $ts = [datetime]::Parse([string]$tx.Stamp); if (($now - $ts).TotalHours -le 48) { $recentDrop[(Clean $tx.Player)] = $ts } } catch {} } }
